<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
import { filterRoundMatches } from '../teamMatches.js'
import { featuredMatch } from '../featuredMatch.js'
import { state, currentRound, isLive, isFinished, isUpcoming, favoriteTeam, day, dateKey, time } from '../state'
import MatchCard from '../components/MatchCard.vue'
import StandingsTable from '../components/StandingsTable.vue'
import Badge from '../components/Badge.vue'
import Icon from '../components/Icon.vue'
import HomePlayerLeaders from '../components/HomePlayerLeaders.vue'
const filter = ref('all'), round = ref(currentRound.value), selectedTeam = ref('')
const followCurrentRound = ref(true)
watch(currentRound, value => { if (followCurrentRound.value) { round.value = value; filter.value = 'all' } })
function selectRound() { followCurrentRound.value = Number(round.value) === currentRound.value; filter.value = 'all' }
const rounds = computed(() => [...new Set(state.matches.map(m => m.round).filter(Boolean))].sort((a, b) => a - b))
const roundMatches = computed(() => state.matches.filter(m => m.round === Number(round.value)))
const clubMatches = computed(() => filterRoundMatches(state.matches, { round: round.value, teamId: selectedTeam.value }))
const liveCount = computed(() => clubMatches.value.filter(isLive).length)
const clubOptions = computed(() => [...state.teams].sort((a, b) => a.name.localeCompare(b.name, 'fr')))
const matches = computed(() => filterRoundMatches(state.matches, { round: round.value, teamId: selectedTeam.value, status: filter.value }))
const groups = computed(() => { const grouped = new Map(); for (const m of matches.value) { const key = dateKey(m.date); if (!grouped.has(key)) grouped.set(key, []); grouped.get(key).push(m) } return [...grouped].map(([date, fixtures]) => ({ date, fixtures })) })
const nextFavorite = computed(() => [...state.matches].filter(m => [m.home.id, m.away.id].includes(state.favorite) && (isLive(m) || isUpcoming(m))).sort((a, b) => Number(isLive(b)) - Number(isLive(a)) || new Date(a.date) - new Date(b.date))[0])
const favoriteRank = computed(() => state.standings.find(s => s.team.id === state.favorite))
const now = ref(Date.now())
let clock
onMounted(() => { clock = setInterval(() => { now.value = Date.now() }, 60000) })
onUnmounted(() => clearInterval(clock))
const featured = computed(() => featuredMatch(state.matches, state.standings, state.favorite, now.value))
const heroMatch = computed(() => featured.value?.match)
const roundRange = computed(() => { if (!roundMatches.value.length) return ''; const dates = roundMatches.value.map(m => m.date).sort(); return `${day(dates[0], { month: 'short' })} — ${day(dates.at(-1), { month: 'short', year: 'numeric' })}` })
function showAllMatches() { filter.value = 'all'; selectedTeam.value = ''; round.value = currentRound.value; followCurrentRound.value = true; document.getElementById('rencontres')?.focus({ preventScroll: true }) }
function changeRound(delta) { const index = rounds.value.indexOf(Number(round.value)); if (rounds.value[index + delta]) { round.value = rounds.value[index + delta]; selectRound() } }
</script>
<template>
  <h1 class="sr-only">Ligue 1 Live : matchs, résultats et classement</h1>
  <div class="dashboard-grid home-dashboard"><section class="hero home-hero"><div class="hero-field" aria-hidden="true"><div class="field-circle"></div><div class="field-box"></div></div><div v-if="heroMatch" class="hero-feature"><div class="feature-top"><h2 class="feature-label">{{ featured.isToday ? 'Match du jour' : 'Prochain rendez-vous' }}</h2><span v-if="isLive(heroMatch)" class="feature-live"><span class="live-dot"></span>{{ state.mode === 'demo' ? 'DIRECT SIMULÉ' : 'EN COURS' }}</span><span v-else>J{{ heroMatch.round }}</span></div><p class="feature-date">{{ day(heroMatch.date, { weekday: 'long', month: 'short' }) }} · {{ time(heroMatch.date) }}</p><RouterLink :to="`/matchs/${heroMatch.id}`" class="feature-match" :aria-label="`Voir le match ${heroMatch.home.name} contre ${heroMatch.away.name}`"><div><Badge :team="heroMatch.home" size="large" /><span class="feature-team-name">{{ heroMatch.home.name }}</span></div><div class="feature-score"><strong>{{ heroMatch.homeGoals ?? '–' }}<span>:</span>{{ heroMatch.awayGoals ?? '–' }}</strong><span>{{ isLive(heroMatch) ? heroMatch.status === 'HT' ? 'Mi-temps' : heroMatch.elapsed ? `${heroMatch.elapsed}′ · En cours` : 'En cours' : isFinished(heroMatch) ? 'Terminé' : time(heroMatch.date) }}</span></div><div><Badge :team="heroMatch.away" size="large" /><span class="feature-team-name">{{ heroMatch.away.name }}</span></div></RouterLink><p class="feature-reason"><span class="feature-reason-icon" aria-hidden="true">★</span><strong>Pourquoi ce match ?</strong>{{ featured.reason }}</p><a href="#rencontres" class="feature-link" @click="showAllMatches">Voir tous les matchs <Icon name="arrow" :size="16" /></a></div><div v-else class="hero-feature feature-empty"><span class="feature-label">LE CHAMPIONNAT</span><p>Aucun prochain match disponible dans le calendrier reçu.</p><a href="#rencontres" class="feature-link" @click="showAllMatches">Voir tous les matchs <Icon name="arrow" :size="16" /></a></div><span class="hero-watermark" aria-hidden="true">{{ String(round).padStart(2, '0') }}</span></section>
  <section id="rencontres" class="match-section" tabindex="-1"><div class="section-heading"><div><span class="eyebrow">LE CHAMPIONNAT AU QUOTIDIEN</span><h2>Les rencontres<span class="heading-dot">.</span></h2></div></div><div class="round-toolbar"><div class="round-selector"><button class="icon-button" aria-label="Journée précédente" :disabled="Number(round) === rounds[0]" @click="changeRound(-1)"><Icon name="back" :size="16" /></button><label><span class="sr-only">Choisir la journée</span><select v-model="round" @change="selectRound"><option v-for="r in rounds" :key="r" :value="r">Journée {{ String(r).padStart(2, '0') }}</option></select></label><button class="icon-button" aria-label="Journée suivante" :disabled="Number(round) === rounds.at(-1)" @click="changeRound(1)"><Icon name="arrow" :size="16" /></button></div><label class="club-filter"><span class="sr-only">Filtrer par club</span><select v-model="selectedTeam"><option value="">Tous les clubs</option><option v-for="club in clubOptions" :key="club.id" :value="club.id">{{ club.name }}</option></select></label></div><div class="round-period"><span>{{ roundRange }}</span><button v-if="!followCurrentRound" class="text-button" @click="showAllMatches">Revenir à la journée en cours</button></div><div class="filters"><div class="filter-tabs" role="group" aria-label="Filtrer les matchs"><button :class="{ active: filter === 'all' }" :aria-pressed="filter === 'all'" @click="filter = 'all'">Tous <span>{{ clubMatches.length }}</span></button><button :class="{ active: filter === 'live' }" :aria-pressed="filter === 'live'" @click="filter = 'live'"><span class="live-dot"></span>En cours <span>{{ liveCount }}</span></button><button :class="{ active: filter === 'upcoming' }" :aria-pressed="filter === 'upcoming'" @click="filter = 'upcoming'">À venir</button><button :class="{ active: filter === 'finished' }" :aria-pressed="filter === 'finished'" @click="filter = 'finished'">Terminés</button></div><button v-if="favoriteTeam" class="favorite-filter icon-button" :class="{ selected: Number(selectedTeam) === state.favorite }" :aria-pressed="Number(selectedTeam) === state.favorite" aria-label="Afficher uniquement mon équipe" @click="selectedTeam = Number(selectedTeam) === state.favorite ? '' : state.favorite"><Icon name="heart" :size="18" /></button></div><div v-for="group in groups" :key="group.date" class="match-day"><div class="day-heading"><h3>{{ day(group.fixtures[0].date, { weekday: 'long' }) }}</h3><span>{{ group.fixtures.length }} MATCH{{ group.fixtures.length > 1 ? 'S' : '' }}</span></div><div class="match-grid"><MatchCard v-for="match in group.fixtures" :key="match.id" :match="match" horizontal /></div></div><div v-if="!matches.length" class="empty panel"><Icon name="matches" :size="36" /><h3>Aucun match ici pour le moment</h3><p>{{ selectedTeam ? 'Cette équipe ne correspond pas à ce filtre.' : 'Essayez un autre filtre ou une autre journée.' }}</p><button class="text-button" @click="filter = 'all'; selectedTeam = ''">Afficher tous les matchs</button></div><div class="update-note"><Icon name="clock" :size="13" /><span>{{ state.mode === 'demo' ? 'Scénario fictif · aucune actualisation des scores' : `Données mises à jour à ${time(state.fetchedAt)} · ${day(state.fetchedAt, { month: 'short' })} · ${state.refreshMode === 'pause' ? 'actualisation en pause' : state.refreshMode === 'manual' ? 'actualisation manuelle' : 'vérification pendant les matchs'}` }}</span></div></section>
  <aside class="dashboard-aside"><section class="panel favorite-panel"><div class="aside-heading"><span class="eyebrow">MON ÉQUIPE</span><Icon name="heart" :size="17" /></div><template v-if="favoriteTeam"><div class="favorite-club"><Badge :team="favoriteTeam" size="large" /><div><h3>{{ favoriteTeam.name }}</h3><span>{{ favoriteRank ? `${favoriteRank.rank}${favoriteRank.rank === 1 ? 'er' : 'e'} du classement · ${favoriteRank.points} points` : 'Votre club favori' }}</span></div></div><p class="aside-subtitle">{{ nextFavorite && isLive(nextFavorite) ? 'MATCH EN COURS' : 'PROCHAIN RENDEZ-VOUS' }}</p><RouterLink v-if="nextFavorite" :to="`/matchs/${nextFavorite.id}`" class="next-match"><span>{{ nextFavorite.home.code }} <b>vs</b> {{ nextFavorite.away.code }}</span><span>{{ day(nextFavorite.date, { month: 'short' }) }} · {{ time(nextFavorite.date) }}</span></RouterLink><p v-else class="muted">Aucun prochain match disponible.</p><RouterLink to="/mon-equipe" class="button full">Suivre mon équipe <Icon name="arrow" :size="15" /></RouterLink><button class="text-button small-text" @click="state.pickerOpen = true">Changer d’équipe</button></template><template v-else><div class="favorite-art"><Icon name="heart" :size="34" /></div><h3>Un club. Votre passion.</h3><p>Gardez votre équipe favorite<br />au plus près du terrain.</p><button class="button primary full" :disabled="!state.teams.length" @click="state.pickerOpen = true">Choisir mon équipe <Icon name="arrow" :size="15" /></button><span class="small-text muted">Sans compte, en un clic.</span></template></section><section class="panel mini-table"><div class="aside-heading"><h3>Classement · forme</h3><Icon name="trophy" :size="17" /></div><StandingsTable :rows="state.standings.slice(0, 5)" compact show-form /><RouterLink to="/classement" class="aside-footer-link">Tout le classement <Icon name="arrow" :size="15" /></RouterLink></section><template v-if="state.source !== 'highlightly'"><HomePlayerLeaders kind="scorers" /><HomePlayerLeaders kind="assists" /></template><div class="editorial-note"><span class="little-square"></span><p><strong>Le jeu avant tout.</strong><br />Une seule compétition.<br />Toute votre passion.</p><span class="editorial-number">01</span></div></aside></div>
</template>
